import{_ as t,c as l,aU as s,a}from"./chunks/framework.DIXiA2XH.js";const u=JSON.parse('{"title":"MQ","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/MQ.md","filePath":"note/back-end/mianshi/MQ.md","lastUpdated":1768133062000}'),i={name:"note/back-end/mianshi/MQ.md"};function n(p,e,o,r,h,d){return a(),l("div",null,[...e[0]||(e[0]=[s(`<h1 id="mq" tabindex="-1">MQ <a class="header-anchor" href="#mq" aria-label="Permalink to &quot;MQ&quot;">​</a></h1><h2 id="rocketmq" tabindex="-1">RocketMQ <a class="header-anchor" href="#rocketmq" aria-label="Permalink to &quot;RocketMQ&quot;">​</a></h2><h3 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h3><ul><li>Topic（主题）</li><li>Queue（队列）：一个Topic由多个Queue组成，消息被均匀地分布在这些Queue中。队列是消息存储和传输的实际载体。</li><li>Consumer Group（消费者组）</li><li>Consumer Instance（消费者实例）</li></ul><p><strong>一个Queue只能被同一个Consumer Group下的一个Consumer Instance消费。但一个Consumer Instance可以同时消费多个Queue。</strong></p><p>队列是什么？和Topic有什么关系？</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>队列（Queue） 是Topic的分区（Partition） 单位。当你创建一个Topic时，必须指定它包含多少个Queue（例如8个、16个）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>消息不是直接存在Topic里的，而是存储在Topic下的各个Queue中。生产者发送消息到某个Topic，这条消息会根据一定的策略（如轮询、哈希）被路由到该Topic下的某一个Queue里。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>关系：Topic是逻辑概念，Queue是物理概念。Topic是逻辑上的消息分类，而Queue是实际承载消息的实体。可以把Topic理解成一个由多个Queue组成的逻辑队列。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>在创建Topic的时候要指定队列么？</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>是的，必须指定。 这是在创建Topic时最重要的参数之一（通常在管理控制台或通过命令创建时指定）。</span></span>
<span class="line"><span>例如，创建命令通常是这样的：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>sh mqadmin updateTopic -n 127.0.0.1:9876 -c DefaultCluster -t YOUR_TOPIC_NAME -r 8 -w 8</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这里的 -r 8 -w 8 通常就表示读写队列数各为8个。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><h3 id="rocketmq消费模式有几种" tabindex="-1">RocketMQ消费模式有几种？ <a class="header-anchor" href="#rocketmq消费模式有几种" aria-label="Permalink to &quot;RocketMQ消费模式有几种？&quot;">​</a></h3><p>消费模型由Consumer决定，消费维度为Topic。</p><ol><li>集群消费</li></ol><ul><li>一条消息只会被同Group中的一个Consumer消费</li><li>多个Group同时消费一个Topic时，每个Group都会有一个Consumer消费到数据</li></ul><ol start="2"><li>广播消费</li></ol><p>消息将对一 个Consumer Group 下的各个 Consumer 实例都消费一遍。即即使这些 Consumer 属于同一个Consumer Group ，消息也会被 Consumer Group 中的每个 Consumer 都消费一次。</p><h3 id="rocketmq消费消息是push还是pull" tabindex="-1">RocketMQ消费消息是push还是pull？ <a class="header-anchor" href="#rocketmq消费消息是push还是pull" aria-label="Permalink to &quot;RocketMQ消费消息是push还是pull？&quot;">​</a></h3><p>RocketMQ没有真正意义的push，都是pull，虽然有push类，但实际底层实现采用的是长轮询机制，即拉取方式</p><blockquote><p>broker端属性 longPollingEnable 标记是否开启长轮询。默认开启</p></blockquote><h3 id="一个队列只能被一个同group的消费者实例消费如何理解" tabindex="-1">一个队列只能被一个同Group的消费者实例消费如何理解？ <a class="header-anchor" href="#一个队列只能被一个同group的消费者实例消费如何理解" aria-label="Permalink to &quot;一个队列只能被一个同Group的消费者实例消费如何理解？&quot;">​</a></h3><p>这意味着对于同一个消费者组（Consumer Group）来说，它的所有实例会<strong>共同协商</strong>（通过RocketMQ的负载均衡机制）来分配某个Topic下的所有Queue。</p><ul><li><p><strong>场景一：消费者实例数 = 队列数（理想状态）</strong></p><ul><li>Topic <code>OrderTopic</code> 有 4 个 Queue (Q1, Q2, Q3, Q4)。</li><li>你的消费者组 <code>OrderGroup</code> 启动了 4 个实例 (C1, C2, C3, C4)。</li><li>负载均衡后，分配结果是： <ul><li>C1 -&gt; Q1</li><li>C2 -&gt; Q2</li><li>C3 -&gt; Q3</li><li>C4 -&gt; Q4</li></ul></li><li>每个消费者实例都“认领”了一个队列，分工明确，效率最高。</li></ul></li><li><p><strong>场景二：消费者实例数 &lt; 队列数（很常见）</strong></p><ul><li><code>OrderTopic</code> 还是有 4 个 Queue (Q1, Q2, Q3, Q4)。</li><li><code>OrderGroup</code> 只启动了 2 个实例 (C1, C2)。</li><li>负载均衡后，分配结果可能是： <ul><li>C1 -&gt; Q1, Q2</li><li>C2 -&gt; Q3, Q4</li></ul></li><li>每个消费者实例需要处理两个队列的消息，只要它们的处理能力跟得上，也没问题。</li></ul></li><li><p><strong>场景三：消费者实例数 &gt; 队列数（资源浪费！）</strong></p><ul><li><code>OrderTopic</code> 只有 4 个 Queue (Q1, Q2, Q3, Q4)。</li><li><code>OrderGroup</code> 却启动了 6 个实例 (C1, C2, C3, C4, C5, C6)。</li><li>负载均衡后，分配结果只能是： <ul><li>C1 -&gt; Q1</li><li>C2 -&gt; Q2</li><li>C3 -&gt; Q3</li><li>C4 -&gt; Q4</li><li>C5 -&gt; <strong>（无队列可分配，处于空闲状态）</strong></li><li>C6 -&gt; <strong>（无队列可分配，处于空闲状态）</strong></li></ul></li><li><strong>C5和C6无法消费任何消息，白白浪费了服务器资源。</strong></li></ul></li></ul><hr><h3 id="rocketmq如何保证消息不丢失" tabindex="-1">RocketMQ如何保证消息不丢失？ <a class="header-anchor" href="#rocketmq如何保证消息不丢失" aria-label="Permalink to &quot;RocketMQ如何保证消息不丢失？&quot;">​</a></h3><ol><li>生产者同步发送消息，失败重试，再失败告警+落库</li><li>broke默认是异步刷盘+集群部署</li><li>消费完成ack确认</li></ol><h3 id="rocketmq的消息堆积如何处理" tabindex="-1">rocketMQ的消息堆积如何处理？ <a class="header-anchor" href="#rocketmq的消息堆积如何处理" aria-label="Permalink to &quot;rocketMQ的消息堆积如何处理？&quot;">​</a></h3><ol><li>修改topic队列数，同时增加消费者数量</li><li>优化代码，提高业务处理速度</li><li>将topic落库或者写脚本转移到一个新的topic中。</li></ol><h3 id="消息消费失败后会怎么样" tabindex="-1">消息消费失败后会怎么样 <a class="header-anchor" href="#消息消费失败后会怎么样" aria-label="Permalink to &quot;消息消费失败后会怎么样&quot;">​</a></h3><p>RocketMQ 在消息消费失败时，确实会将消息投送到重试队列。不过，在实际工作中，不需要主动同时监听原始 Topic 和对应的重试队列 Topic，因为 RocketMQ 的消费者客户端会自动处理重试队列的订阅。</p><p>当消息消费失败时，RocketMQ 会自动将消息重新投递到重试队列，。重试队列的命名格式通常是 %RETRY%+消费者组名（例如 <code>%RETRY%my_consumer_group</code>），而不是直接与原始 Topic 名称关联</p><p>RocketMQ 的重试机制采用时间衰减策略，即重试间隔会随着重试次数的增加而不断延长。默认最大重试次数为 16 次。</p><p>如果超过最大重试次数消息仍未消费成功，该消息会被投递到死信队列（Dead-Letter Queue, DLQ），其命名格式为 <code>%DLQ%+消费者组名</code></p><p><strong>是否需要监听两个 Topic？</strong></p><p>不需要，RocketMQ 的消费者客户端在设计上已经考虑到了重试逻辑。当你使用 <code>DefaultMQPushConsumer</code> 并订阅了原始 Topic（例如 Topic A）时，RocketMQ 客户端会自动为你订阅并监听对应的重试队列（<code>%RETRY%&lt;YourConsumerGroupName&gt;</code>）</p><h3 id="延迟消息" tabindex="-1">延迟消息 <a class="header-anchor" href="#延迟消息" aria-label="Permalink to &quot;延迟消息&quot;">​</a></h3><p>RocketMQ通过内置的延迟级别和定时调度机制来实现延迟消息，而不是用死信队列。 它提供了18个固定的延迟等级，比如等级14对应10分钟。我们下单支付的场景，设置等级14即可。</p><p>RocketMQ不支持任意时间的延迟，而是预设了18个固定的延迟等级（Level），每个等级对应一个固定的延迟时间。</p><table tabindex="0"><thead><tr><th style="text-align:left;">延迟等级 (Level)</th><th style="text-align:left;">1</th><th style="text-align:left;">2</th><th style="text-align:left;">3</th><th style="text-align:left;">4</th><th style="text-align:left;">5</th><th style="text-align:left;">6</th><th style="text-align:left;">7</th><th style="text-align:left;">8</th><th style="text-align:left;">9</th><th style="text-align:left;">10</th><th style="text-align:left;">11</th><th style="text-align:left;">12</th><th style="text-align:left;">13</th><th style="text-align:left;">14</th><th style="text-align:left;">15</th><th style="text-align:left;">16</th><th style="text-align:left;">17</th><th style="text-align:left;">18</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>延迟时间</strong></td><td style="text-align:left;">1s</td><td style="text-align:left;">5s</td><td style="text-align:left;">10s</td><td style="text-align:left;">30s</td><td style="text-align:left;">1m</td><td style="text-align:left;">2m</td><td style="text-align:left;">3m</td><td style="text-align:left;">4m</td><td style="text-align:left;">5m</td><td style="text-align:left;">6m</td><td style="text-align:left;">7m</td><td style="text-align:left;">8m</td><td style="text-align:left;">9m</td><td style="text-align:left;">10m</td><td style="text-align:left;">20m</td><td style="text-align:left;">30m</td><td style="text-align:left;">1h</td><td style="text-align:left;">2h</td></tr></tbody></table><p>示例代码（Java）：</p><div class="language-java vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Message msg </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Order_Topic&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;订单ID001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;订单超期的逻辑&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getBytes</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 设置延迟等级为14，即10分钟</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">msg.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setDelayTimeLevel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">14</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">producer.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">send</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(msg);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>核心流程</strong>：</p><ul><li>“生产者发送消息时指定一个DelayLevel。”</li><li>“Broker收到后会把消息转移到对应Level的内部主题（SCHEDULE_TOPIC_XXX）暂存。”</li><li>“Broker内部的ScheduleService会定时扫描这些内部主题，一旦发现消息到期，就将其恢复原主题和队列，重新投递。”</li><li>“最终，消费者从原始主题消费到这条延迟消息，完成超时检查逻辑。”</li></ul><p>如何自定义时间呢？mq只给了预设的18个时间级别，那么我们只能通过业务来实现了，可以将过期消息计算好携带到消息里面， 如果发现消息还没到期，就重新计算时间投递就行了。</p><h2 id="什么情况下会导致消息重试" tabindex="-1">什么情况下会导致消息重试 <a class="header-anchor" href="#什么情况下会导致消息重试" aria-label="Permalink to &quot;什么情况下会导致消息重试&quot;">​</a></h2><ol><li>消费者已经消费，但是服务器（Broker）没有及时收到确认（ACK），导致Broker认为消息消费失败，从而将其重新投递或放回队列</li><li>消费者超时未响应（并发消费默认15分钟），Broker会重新投递该消息</li></ol>`,44)])])}const k=t(i,[["render",n]]);export{u as __pageData,k as default};
